import {sourceTrailCases,sourceTrailPages} from './source-trail-content.mjs';
import {trailView,startTrail,resumeTrail,setTrailPage,setTrailCard,chooseTrailAnswer,addTrailSupport,checkTrail,trailCheckMatches} from './source-trail-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
function external(url,label){let allowed=false;try{allowed=['http:','https:'].includes(new URL(url).protocol);}catch{}return allowed?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}<span class="trail-link-url"> ${esc(url)}</span></a>`:`<span>${esc(label)}: ${esc(url)}</span>`;}
const ownLabel=(s,id)=>id===null?'No answer chosen':s.choices.find(c=>c.id===id)?.label??'No answer chosen';
function photo(source){const p=source.photo,known=source.pictureVersion===1&&p.src==='./assets/archive-paris-1910-ph8646.jpg'&&p.filename==='lpdp_30184-10.jpg';return `<figure class="trail-photo">${known?`<img src="./assets/archive-paris-1910-ph8646.jpg" width="2769" height="2160" loading="lazy" alt="${esc(p.alt)}"><a class="trail-full-image" href="./assets/archive-paris-1910-ph8646.jpg" target="_blank" rel="noopener">Open the complete photograph</a>`:`<div class="trail-picture-fallback"><p>This saved picture version or image reference is unavailable here. Its saved description remains:</p><p>${esc(p.alt)}</p><p>Saved image reference: ${esc(p.src)}</p></div>`}<figcaption><strong>${esc(p.credit)}</strong><br>${esc(p.license)} · ${esc(p.inventory)} · ${esc(p.filename)}<br>${external(p.url,'Museum source')} · ${external(p.licenseUrl,'Rights')} · ${external(p.manifest,'Manifest')}<p>${esc(p.reproduction)}</p></figcaption></figure>`;}
function card(source,c,{compact=false}={}){const more=`<dl class="trail-metadata"><dt>${c.id==='note'?'Note creator':'Underlying source creator'}</dt><dd>${esc(c.creator)}</dd><dt>Creation / publication</dt><dd>${esc(c.creationLabel)}</dd><dt>Event described</dt><dd>${esc(c.eventLabel)}</dd></dl><p class="trail-notice">${esc(c.notice)}</p><p class="trail-source-link">${external(c.url,c.id==='note'?'Declared source of this note':'Underlying source')}</p>`;return `<article class="trail-card" data-trail-card-content="${c.id}"><h3>${esc(c.title)}</h3><p class="trail-kind">${esc(c.kind)}</p>${c.id==='photo'?photo(source):''}<p class="trail-card-text">${esc(c.text)}</p><p class="trail-provenance"><strong>Source trail:</strong> ${esc(c.provenance)}</p>${compact?`<details><summary>Creator, dates and source limits</summary>${more}</details>`:more}</article>`;}
function viewer(r){return `<section class="trail-viewer" aria-label="Inspect one source card"><div class="trail-card-buttons" role="group" aria-label="Choose the source card to inspect">${r.source.cards.map(c=>button(`data-trail-card="${c.id}" aria-pressed="${r.card===c.id}"`,c.title,r.card===c.id)).join('')}</div>${card(r.source,r.source.cards.find(c=>c.id===r.card),{compact:true})}</section>`;}
function proposed(r){if(r.source.id!=='origin')return '';const definite=r.answer!==null&&r.answer!=='unsure';return `<section class="trail-proposed-link" aria-label="Our proposed source link"><h3>Our proposed source link</h3>${definite?`<p class="trail-link-pair" data-trail-from="note" data-trail-to="${esc(r.answer)}"><span>${esc(r.source.cards.find(c=>c.id==='note').title)}</span><span class="trail-link-arrow" aria-hidden="true">→</span><span class="trail-arrow-text">was made using</span><strong>${esc(ownLabel(r.source,r.answer))}</strong></p><p class="tiny">Arrow means “was made using”. This is our proposed link; checking keeps the supplied explanation.</p>`:`<p>${r.answer==='unsure'?'Not sure yet; no origin link proposed.':'No origin chosen yet; no link proposed.'}</p>`}</section>`;}
function cardsPage(r){return `<h2 id="trail-prompt" tabindex="-1">Read the three source cards</h2><p>A fictional neighbor is preparing a flood-history display. The photograph is historical; B and C are original modern teaching cards.</p>${button('data-trail-page="try"','Next: try the question',true)}<div class="trail-packet">${r.source.cards.map(c=>card(r.source,c)).join('')}</div>${button('data-trail-page="try"','Next: try the question',true)}`;}
function tryPage(r){return `<h2 id="trail-prompt" tabindex="-1">${esc(r.source.prompt)}</h2><div class="trail-try-layout"><section class="trail-answer"><div class="trail-answer-options" role="group" aria-label="Choose an answer to the current source question">${r.source.choices.map(c=>button(`data-trail-answer="${esc(c.id)}" aria-pressed="${r.answer===c.id}"`,c.label+(r.answer===c.id?' · selected':''),r.answer===c.id)).join('')}</div>${button('data-trail-clear-answer','Leave answer blank')}${proposed(r)}${hearButton(r.source.prompt,'Hear this source question')}${button('data-trail-check','Check / keep this trail',true)}<p class="tiny">Checking is open with blank choices. Latest 8 checks stay here; a ninth removes the oldest.</p>${button('data-trail-page="cards"','Look at the source cards')}</section>${viewer(r)}</div>`;}
const recordHeading=(r,c,i)=>i<r.checks.length-1?'Earlier recorded check':trailCheckMatches(r,c)?'Latest check of this answer and support':'Latest check · answer or support changed since';
function frozenSource(source){return `<details class="trail-frozen-source"><summary>Question, choices and complete source packet kept with this check</summary><h4>${esc(source.title)}</h4><p>${esc(source.prompt)}</p><ul>${source.choices.map(c=>`<li>${esc(c.label)}</li>`).join('')}</ul><p>Supplied expected choice: ${esc(ownLabel(source,source.answerId))}.</p><p>Original explanation: ${esc(source.feedback)}</p><p>Help: ${esc(source.help)}</p>${source.cards.map(c=>card(source,c)).join('')}</details>`;}
function checkRecord(r,c,i){return `<section class="trail-record" tabindex="-1"><h3>${recordHeading(r,c,i)}</h3><p class="trail-feedback">${esc(c.feedback)}</p><p><strong>Recorded chosen label:</strong> ${esc(c.selectedLabel===null?'No definite label recorded':c.selectedLabel)}.</p><p><strong>Recorded outcome:</strong> ${c.outcome===null?'unobserved':c.outcome?'fits':'does not fit'}.</p><details><summary>Answer and support kept with this check</summary><p>Recorded answer ID: ${esc(c.input.answer===null?'blank':c.input.answer)}.</p><p>Support requested by this check: ${esc(c.input.support.join(', ')||'none recorded')}.</p><p class="tiny">These are recorded fields, not a new assessment of the historical record.</p></details>${frozenSource(c.source)}</section>`;}
function keptPage(r){return `<h2 id="trail-prompt" tabindex="-1">Our kept source trail</h2>${r.checks.length?checkRecord(r,r.checks.at(-1),r.checks.length-1):'<p>No check is kept yet. The question and cards remain open.</p>'}${button('data-trail-page="try"','Revise our answer',true)} ${button('data-trail-page="cards"','Return to the source cards')}${r.checks.length>1?`<details><summary>Earlier checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkRecord(r,c,i)).join('')}</details>`:''}`;}
function catalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="trail-catalog"><h2>Choose a source question</h2><p>All four questions use the same three cards. Start a separate visit for any question.</p><p class="tiny">Up to 12 readable visits stay here.${n?` Starting now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Earlier visits remain within that limit.'}</p><form id="trail-start-form"><label for="trail-case">Question</label><select id="trail-case" name="case">${sourceTrailCases.map(c=>`<option value="${esc(c.id)}"${v.current?.source.id===c.id?' selected':''}>${esc(c.title)}</option>`).join('')}</select><button type="submit" class="secondary">Start this question</button></form></section>`;}
function history(v){return `${v.rounds.length?`<details><summary>Our source-question visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-trail-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable source work (${v.earlier.length})</summary><p>The original work remains unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function sourceTrailPage(state){const v=trailView(state),r=v.current,header=`<header class="page-heading"><a class="back" href="#workshop"><span aria-hidden="true">←</span> Workshop</a> <a class="back" href="#archive">Travelers’ Archive</a><h1>Follow the Source Trail</h1><p>Trace where our picture note came from before making a display label.</p></header>`;if(v.status==='unavailable')return `<div class="trail-page">${header}<section class="trail-sheet"><h2>Earlier source work is safe</h2><p>This saved format cannot be continued here. Other Workshop tools and the Archive remain open.</p><details><summary>Saved source work</summary><pre>${esc(JSON.stringify(state.sourceTrail,null,2))}</pre></details></section></div>`;return `<div class="trail-page">${header}<section class="trail-sheet">${r?`<nav class="trail-tabs" aria-label="Source Trail pages">${sourceTrailPages.map(p=>button(`data-trail-page="${p}" aria-current="${v.page===p?'page':'false'}"`,({cards:'Cards',try:'Try',kept:'Kept trail'})[p],v.page===p)).join('')}</nav><p class="trail-case-title"><strong>${esc(r.source.title)}</strong>${r.familiar?' · Question visited before':''}</p>`:''}<p id="trail-status" role="status" tabindex="-1"></p>${r?v.page==='try'?tryPage(r):v.page==='kept'?keptPage(r):cardsPage(r):`<h2 id="trail-prompt" tabindex="-1">Two cards can lead back to one photograph</h2><p>Inspect a historical photograph and our modern teaching notes. Different cards do not automatically mean independent observations.</p>${catalog(v)}`}${r?`<details id="trail-help" data-round="${r.id}"><summary>Help us follow the source trail</summary><p>${esc(r.source.help)}</p>${hearButton(r.source.help,'Hear the source-trail explanation')}${button('data-trail-together',r.support.includes('together')?'Thinking together recorded':'We thought together')}</details><details><summary>Choose another source question</summary>${catalog(v)}</details>`:''}</section>${history(v)}</div>`;}
export function sourceTrailNotes(state){const v=trailView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Source Trail · earlier format</summary><pre>${esc(JSON.stringify(state.sourceTrail,null,2))}</pre></details>`;return `<details class="panel trail-page"><summary>Follow the Source Trail (${v.rounds.length} visits)</summary><p>Supplied-choice practice tracing the declared source of a modern teaching note. In the current authored packet, B derives from A and C’s independence is not established; it supplies no positive independent-witness example. Retained visits keep their own source wording. Fitting choices do not establish independent reading, historical explanation, research or general source trust. Source inspection is presentation, separate from support; all questions reuse this packet.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)}</h3><p>Question visited before: ${r.familiar?'yes':'no'}. Current answer: ${esc(ownLabel(r.source,r.answer))}. Current viewer: ${esc(r.card)}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${frozenSource(r.source)}${r.checks.map((c,i)=>checkRecord(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindSourceTrail(state,{save,render,focus}){
 const boundId=trailView(state).current?.id,sameVisit=el=>el.isConnected&&boundId!==undefined&&trailView(state).current?.id===boundId;
 const show=(message='',target='#trail-prompt')=>{const id=trailView(state).current?.id,open=[...document.querySelectorAll('.trail-sheet details[id][data-round][open]')].filter(d=>Number(d.dataset.round)===id).map(d=>d.id);save();render();if(trailView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#trail-status');if(status)status.textContent=message;focus?.(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))fn(b);}));
 const saveSupport=code=>{addTrailSupport(state,code);save();const r=trailView(state).current,h=document.querySelector('.trail-sheet .trail-record h3');if(h&&r?.checks.length){h.textContent=recordHeading(r,r.checks.at(-1),r.checks.length-1);const status=document.querySelector('#trail-status');if(status)status.textContent='Support request recorded. '+h.textContent+'.';}};
 document.querySelector('#trail-start-form')?.addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget;if(!form.isConnected||trailView(state).current?.id!==boundId)return;const r=startTrail(state,new FormData(form).get('case'));show(r?'A source question is ready.':'A new visit cannot be created because its saved visit numbers have reached the supported limit.',r?'#trail-prompt':'#trail-status');});
 document.querySelectorAll('[data-trail-resume]').forEach(b=>b.addEventListener('click',()=>{if(!b.isConnected||trailView(state).current?.id!==boundId)return;show(resumeTrail(state,Number(b.dataset.trailResume))?'Earlier source visit opened with its own packet.':'That visit could not be opened.');}));
 bind('[data-trail-page]',b=>{setTrailPage(state,b.dataset.trailPage);show();});
 bind('[data-trail-card]',b=>{setTrailCard(state,b.dataset.trailCard);show('',`[data-trail-card="${b.dataset.trailCard}"]`);});
 bind('[data-trail-answer]',b=>{chooseTrailAnswer(state,b.dataset.trailAnswer);show('Answer changed. All three source cards remain available.',`[data-trail-answer="${b.dataset.trailAnswer}"]`);});
 bind('[data-trail-clear-answer]',()=>{chooseTrailAnswer(state,null);show('Answer left blank. All three source cards remain available.','[data-trail-clear-answer]');});
 bind('[data-trail-check]',()=>{const c=checkTrail(state);if(c)setTrailPage(state,'kept');show(c?'The answer, support and source packet are kept together.':'This check could not be kept.',c?'.trail-record':'#trail-status');});
 bind('[data-trail-together]',()=>{addTrailSupport(state,'together');show('Thinking together recorded as support.','[data-trail-together]');});
 const fold=document.getElementById('trail-help');fold?.addEventListener('toggle',()=>{if(fold.open&&sameVisit(fold)&&Number(fold.dataset.round)===boundId)saveSupport('help');});
 document.querySelectorAll('.trail-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameVisit(b))saveSupport('audio');}));
}
